const inp = $('Apply Input').first().json;
let b = {};
try { b = $('Get Bundle').first(0).json || {}; } catch (e) { b = {}; }
const e = $input.first().json.error;
const msg = e ? (typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e)) : "Supabase read failed";
return [{ json: {
  chat_id: String(inp.TELEGRAM_STAFF_CHAT_ID || ""),
  language: "en",
  text: null,
  key: "msg_staff_error",
  params: { business_name: b.business_name || "?", entity_id: b.entity_id || "?", bundle_id: inp.bundle_id, error: "Before write, nothing changed in Yext: " + msg },
  lines: [],
  buttons: [],
  edit_message_id: null,
} }];

const inp = $('Apply Input').first().json;
const bundle = $('Get Bundle').first().json || {};
const items = $('Get Items').all().map(i => i.json).filter(r => r && r.bundle_id !== undefined);
const lastRows = $input.all().map(i => i.json).filter(r => r && r.bundle_id !== undefined);
const last = lastRows[0] || null;
const mode = String(inp.mode || "").toUpperCase();
let ok = false;
let reason = null;
if (!bundle.bundle_id) reason = "BUNDLE_NOT_FOUND";
else if (!bundle.yext_entity_id) reason = "NO_YEXT_ENTITY";
else if (mode === "APPLY") {
  ok = bundle.status === "APPROVED";
  if (!ok) reason = "STATUS_" + bundle.status;
} else if (mode === "UNDO") {
  const hrs = Number(inp.UNDO_WINDOW_HOURS || 24);
  const young = !!(last && last.created_at && (Date.now() - new Date(last.created_at).getTime()) <= hrs * 3600 * 1000);
  // Undo is also the way out of APPLY_FAILED (or an APPLYING run that died >10 min ago), as long as a successful apply exists in the window.
  const staleApplying = bundle.status === "APPLYING" && (!bundle.updated_at || Date.now() - new Date(bundle.updated_at).getTime() > 10 * 60000);
  const undoable = ["APPLIED", "APPLY_FAILED"].includes(bundle.status) || staleApplying;
  ok = undoable && young;
  if (!ok) reason = !undoable ? "STATUS_" + bundle.status : "UNDO_WINDOW_EXPIRED";
} else reason = "BAD_MODE";
let pubs = bundle.publishers;
if (typeof pubs === "string") { try { pubs = JSON.parse(pubs); } catch (e) { pubs = []; } }
bundle.publishers = Array.isArray(pubs) ? pubs : [];
return [{ json: {
  guard_ok: ok,
  guard_reason: reason,
  status: ok ? "PASSED" : "SKIPPED_GUARD",
  bundle_id: inp.bundle_id,
  mode,
  notify: String(inp.notify || "OWNER").toUpperCase(),
  cfg: {
    YEXT_BASE_URL: String(inp.YEXT_BASE_URL || "https://sbx-api.yextapis.com/v2/accounts/me").replace(/\/+$/, ""),
    YEXT_VERSION: String(inp.YEXT_VERSION || "20261106"),
    TELEGRAM_STAFF_CHAT_ID: String(inp.TELEGRAM_STAFF_CHAT_ID || ""),
    UNDO_WINDOW_HOURS: Number(inp.UNDO_WINDOW_HOURS || 24),
  },
  bundle,
  items,
  last_apply: last,
} }];

const g = $('Guard').first().json;
const r = $input.first().json;
const errText = x => x ? (typeof x === "object" ? (x.message || JSON.stringify(x)) : String(x)) : "";
const sc = Number(r.statusCode || 0);
if (r.error || sc < 200 || sc >= 300) {
  return [{ json: { proceed: false, error: "YEXT_GET_FAILED " + (sc || "") + " " + (errText(r.error) || errText(r.body && r.body.meta && r.body.meta.errors)) } }];
}
const resp = (r.body && r.body.response) || {};
const hoursBefore = resp.hours ? JSON.parse(JSON.stringify(resp.hours)) : null;
const metaErrors = (r.body && r.body.meta && r.body.meta.errors) || [];
if (metaErrors.length) return [{ json: { proceed: false, error: "YEXT_GET_FAILED " + JSON.stringify(metaErrors), hours_before: hoursBefore } }];

if (g.mode === "UNDO") {
  let prev = g.last_apply ? g.last_apply.hours_before : null;
  if (typeof prev === "string") { try { prev = JSON.parse(prev); } catch (e) { prev = null; } }
  if (!prev || typeof prev !== "object") return [{ json: { proceed: false, error: "UNDO_NO_PREVIOUS_HOURS", hours_before: hoursBefore } }];
  // Yext keeps sub-fields left out of a PUT, so an empty holiday list must be sent explicitly to clear it.
  const undoHours = JSON.parse(JSON.stringify(prev));
  if (!Array.isArray(undoHours.holidayHours)) undoHours.holidayHours = [];
  return [{ json: { proceed: true, hours_before: hoursBefore, new_hours: undoHours, changed: [] } }];
}

if (!hoursBefore) return [{ json: { proceed: false, error: "HOURS_MISSING", hours_before: null } }];
const next = JSON.parse(JSON.stringify(hoursBefore));
if (!Array.isArray(next.holidayHours)) next.holidayHours = [];
const changed = [];
for (const it of g.items) {
  const fh = it.final_hours;
  if (fh === null || fh === undefined || fh === "") continue;
  let entry;
  if (fh === "closed") entry = { date: it.date, isClosed: true };
  else if (fh === "regular") entry = { date: it.date, isRegularHours: true };
  else {
    const intervals = String(fh).split(",").map(p => { const s = p.trim().split("-"); return { start: s[0], end: s[1] }; });
    entry = { date: it.date, openIntervals: intervals };
  }
  next.holidayHours = next.holidayHours.filter(h => h.date !== it.date);
  next.holidayHours.push(entry);
  changed.push({ date: it.date, day_name: it.day_name, hours: fh, entry });
}
next.holidayHours.sort((a, b) => String(a.date).localeCompare(String(b.date)));
if (!changed.length) return [{ json: { proceed: false, error: "NO_FINAL_HOURS", hours_before: hoursBefore } }];
return [{ json: { proceed: true, hours_before: hoursBefore, new_hours: next, changed } }];

const g = $('Guard').first().json;
const pick = fn => { try { const r = fn(); return (r && r.json) ? r.json : null; } catch (e) { return null; } };
const errText = x => x ? (typeof x === "object" ? (x.message || JSON.stringify(x)) : String(x)) : "";
const ok2xx = r => r && !r.error && Number(r.statusCode) >= 200 && Number(r.statusCode) < 300;
const metaErr = r => (r && r.body && r.body.meta && Array.isArray(r.body.meta.errors)) ? r.body.meta.errors : [];
function canon(v) {
  if (Array.isArray(v)) {
    const arr = v.map(canon);
    if (arr.every(x => x && typeof x === "object" && "date" in x)) arr.sort((a, b) => String(a.date).localeCompare(String(b.date)));
    return arr;
  }
  if (v && typeof v === "object") {
    const o = {};
    Object.keys(v).sort().forEach(k => { if (v[k] !== null && v[k] !== undefined) o[k] = canon(v[k]); });
    return o;
  }
  return v;
}
const same = (a, b) => JSON.stringify(canon(a)) === JSON.stringify(canon(b));
// Yext omits holidayHours when the list is empty: treat a missing list as [] when comparing.
const withHH = h => { const c = h && typeof h === "object" ? JSON.parse(JSON.stringify(h)) : {}; if (!Array.isArray(c.holidayHours)) c.holidayHours = []; return c; };

const incoming = $input.first().json;
const built = pick(() => $('Build New Hours').first(0));
const put = pick(() => $('Yext PUT').first(0)) || pick(() => $('Yext PUT').first(1));
const after = pick(() => $('Yext Get After').first(0)) || pick(() => $('Yext Get After').first(1));
let status = "FAILED";
let error = null;
let hoursBefore = built ? (built.hours_before ?? null) : null;
let hoursAfter = null;

if (!built) {
  error = "BEFORE_WRITE_FAILED: " + (errText(incoming.error) || "status update or Yext read failed");
} else if (!built.proceed) {
  error = built.error || "NOT_READY";
} else if (!put) {
  error = "PUT_NOT_EXECUTED: " + errText(incoming.error);
} else if (!ok2xx(put) || metaErr(put).length) {
  error = "YEXT_PUT_FAILED " + (put.statusCode || "") + " " + (errText(put.error) || JSON.stringify(metaErr(put)));
} else if (!after || !ok2xx(after) || metaErr(after).length) {
  status = "VERIFY_MISMATCH";
  error = "VERIFY_READ_FAILED " + ((after && after.statusCode) || "") + " " + errText(after && after.error);
} else {
  hoursAfter = (after.body && after.body.response && after.body.response.hours) || null;
  if (g.mode === "UNDO") {
    if (same(withHH(hoursAfter), withHH(built.new_hours))) status = "SUCCESS";
    else { status = "VERIFY_MISMATCH"; error = "UNDO_HOURS_DIFFER"; }
  } else {
    const hh = (hoursAfter && Array.isArray(hoursAfter.holidayHours)) ? hoursAfter.holidayHours : [];
    const bad = built.changed.filter(c => !same(hh.find(h => h.date === c.date) || null, c.entry)).map(c => c.date);
    if (!bad.length) status = "SUCCESS";
    else { status = "VERIFY_MISMATCH"; error = "DATES_NOT_VERIFIED: " + bad.join(", "); }
  }
}
// Yext is provably untouched when nothing was written, or Yext rejected the PUT with 4xx.
const putSc = put ? Number(put.statusCode || 0) : 0;
const yextUntouched = status !== "SUCCESS" && (!built || !built.proceed || (!!put && !put.error && putSc >= 400 && putSc < 500));
let newBundleStatus;
if (status === "SUCCESS") newBundleStatus = g.mode === "UNDO" ? "UNDONE" : "APPLIED";
else if (g.mode === "UNDO" && yextUntouched) newBundleStatus = g.bundle.status === "APPLY_FAILED" || g.bundle.status === "APPLYING" ? "APPLY_FAILED" : "APPLIED";
else newBundleStatus = "APPLY_FAILED";
return [{ json: { status, error, mode: g.mode, bundle_id: g.bundle_id, yext_entity_id: g.bundle.yext_entity_id, hours_before: hoursBefore, hours_after: hoursAfter, new_bundle_status: newBundleStatus, yext_untouched: yextUntouched } }];

const v = $('Verify').first().json;
return [{ json: {
  bundle_id: v.bundle_id,
  yext_entity_id: v.yext_entity_id,
  mode: v.mode,
  hours_before: v.hours_before,
  hours_after: v.hours_after,
  status: v.status,
  error: v.error,
} }];

const g = $('Guard').first().json;
const v = $('Verify').first().json;
const b = g.bundle;
const lang = ["fi", "sv", "nb", "en"].includes(b.language) ? b.language : "en";
const display = h => h === "closed" ? "{@label_closed}" : h === "regular" ? "{@label_regular}" : String(h).split(",").map(x => x.trim().replace("-", "–")).join(", ");
const btn = (key, action) => ({ key, data: action + ":" + b.bundle_id });
const out = [];
const owner = (key, lines, buttons) => {
  if (!b.telegram_chat_id) return;
  out.push({ json: { chat_id: String(b.telegram_chat_id), language: lang, text: null, key, params: {}, lines, buttons, edit_message_id: null } });
};

if (v.status === "SUCCESS" && v.mode === "APPLY") {
  const lines = g.items.filter(i => i.final_hours).sort((x, y) => String(x.date).localeCompare(String(y.date)))
    .map(i => "• " + (i.day_name || i.date) + ": " + display(i.final_hours));
  const secs = p => Number(p.seconds ?? p.typicalUpdateSpeedSeconds) || 0;
  [...b.publishers].sort((x, y) => secs(x) - secs(y)).forEach(p => {
    const s = secs(p);
    lines.push("• " + (p.name || p.publisherName || p.publisherId) + " ~" + (s >= 3600 ? Math.round(s / 3600) + " h" : Math.max(1, Math.round(s / 60)) + " min"));
  });
  let buttons;
  if (!b.has_permission) {
    lines.push("{@msg_permission_offer}");
    buttons = [btn("btn_undo", "u"), btn("btn_permission_yes", "p"), btn("btn_not_now", "n")];
  } else {
    buttons = [btn("btn_undo", "u"), btn("btn_edit", "e"), btn("btn_not_now", "n")];
  }
  owner(g.notify === "AUTO" ? "msg_auto_applied" : "msg_applied", lines, buttons);
  if (b.telegram_message_id && b.telegram_chat_id) {
    out.push({ json: { chat_id: String(b.telegram_chat_id), language: lang, text: String(b.intro_text || "") + "\n✅", key: null, params: {}, lines: [], buttons: [], edit_message_id: String(b.telegram_message_id) } });
  }
} else if (v.status === "SUCCESS" && v.mode === "UNDO") {
  owner("msg_undone", [], [btn("btn_edit", "e"), btn("btn_regular", "qr"), btn("btn_not_now", "n")]);
} else {
  // Always leave the owner a way forward: retry the same action, or edit (APPLY_FAILED accepts a, e and u).
  let failButtons;
  if (v.new_bundle_status === "APPLIED") failButtons = [btn("btn_undo", "u")];
  else if (v.mode === "UNDO") failButtons = [btn("btn_retry", "u"), btn("btn_edit", "e")];
  else failButtons = [btn("btn_retry", "a"), btn("btn_edit", "e")];
  owner("msg_apply_failed", [], failButtons);
  const note = v.yext_untouched ? " (Yext unchanged; status " + v.new_bundle_status + ")" : " (Yext state uncertain; status " + v.new_bundle_status + ")";
  out.push({ json: {
    chat_id: g.cfg.TELEGRAM_STAFF_CHAT_ID, language: "en", text: null, key: "msg_staff_error",
    params: { business_name: b.business_name || "?", entity_id: b.entity_id || "?", bundle_id: b.bundle_id, error: v.mode + " " + v.status + ": " + (v.error || "unknown") + note },
    lines: [], buttons: [], edit_message_id: null,
  } });
}
return out;
